LLAMA = 'Llama-3.2-1B-Instruct-q4f16_1-MLC'
EXEC = ['simulado', 'no-navegador', 'sua-chave']

def ex(*qs): return [{'pt': q['pt'], 'en': q['en']} for q in qs]
def LQ(pt, en): return {'pt': pt, 'en': en}

def real_for(op, args):
    return {'no-navegador': {'adapter': 'declarative', 'model': LLAMA, 'op': op, 'args': args},
            'sua-chave': {'adapter': 'declarative', 'op': op, 'args': args}}

def teacher(pt, en):
    return {'pt': pt, 'en': en}

YN = lambda T: T('Use sim ou nao.', 'Use yes or no.')

def fm(x):
    """Expression that formats the number in var x with the locale's thousands/decimal separators (data: tsep, dsep)."""
    i = f'floor({x})'; th = f'floor({i} / 1000)'; rest = f'({i} - {th} * 1000)'; c = f'round(({x} - {i}) * 100)'
    return (f"({i} >= 1000 ? {th} + tsep + ({rest} < 10 ? '00' : ({rest} < 100 ? '0' : '')) + {rest} : {i})"
            f" + ({c} > 0 ? dsep + ({c} < 10 ? '0' : '') + {c} : '')")
SEPS = lambda T: {'tsep': T('.', ','), 'dsep': T(',', '.')}

