E2 = LQ('Fui cobrado duas vezes pelo pedido 7301 no cartão.', 'I was charged twice for order 7301 on my card.')
E3 = LQ('Não consigo trocar a senha do portal: o link por e-mail não chega.', 'I can’t change my portal password: the email link never arrives.')

s17 = step('p-exemplos-few-shot-e-formato', 17, 15, ['prompts', 'few-shot', 'exemplos', 'formato', 'suporte'],
 ['p-prompt-de-sistema-e-papeis'], EXEC, LQ('assunto', 'subject'),
 {'name': 'text', 'required': False, 'ui': 'examples', 'default': E1, 'examples': ex(E1, E2, E3)},
 [flag('count', 'exemplos', 'examples', 'int', min=0, max=5, default=3, ui='slider'),
  flag('varied', 'variedade', 'variety', 'bool', default=True, ui='switch')],
 {'options': ['free', 'format', 'error'], 'answer': 'free'}, 'copycat',
 {'live': False,
  'consts': {'real': False, 'realOutput': ''},
  'compute': {
   'rec': 'lookup(emails, text, unknownEmail)',
   'shots': 'varied ? shotsVaried : shotsSame',
   'shown': 'slice(shots, 0, count)',
   'sysText': "sysBase + (count > 0 ? '\n<examples>\n' + join(shown, '\n') + '\n</examples>' : '')",
   'distinct': 'count == 0 ? 0 : (varied ? count : 1)',
   'simCat': 'distinct >= 2 ? rec.cat : exCat',
   'simOut': "count == 0 ? rec.free : '[' + simCat + '] ' + rec.summary + (rec.num != '' ? ' (#' + rec.num + ')' : '')",
   'out': 'real ? realOutput : simOut',
   'fmtOk': "includes(out, '[') && includes(out, '] ')",
   'catOk': "real ? includes(lower(out), lower('[' + rec.cat + ']')) : simCat == rec.cat",
   'numOk': "rec.num == '' || includes(out, '#' + rec.num)"},
  'cases': [
   {'when': 'fmtOk && catOk', 'flags': ['good']},
   {'when': '!fmtOk', 'flags': ['freeform']},
   {'when': 'fmtOk && !catOk', 'flags': ['copycat']},
   {'when': 'true', 'vars': {'out': 'out', 'count': 'count', 'distinct': 'distinct', 'cat': 'rec.cat'}}],
  'widgets': [
   {'type': 'terminal', 'label': '@prompt', 'lines': "=concat(['$ system', '~ ' + sysBase], count > 0 ? concat(['~ <examples>'], shown, ['~ </examples>']) : ['~ ' + noShots], ['$ user: ' + text])"},
   {'type': 'note', 'tone': "=fmtOk && catOk ? 'ok' : 'bad'", 'text': '=out'},
   {'type': 'metrics', 'items': [{'label': '@count', 'value': '=count', 'format': 'int', 'tone': 'info'},
                                 {'label': '@distinct', 'value': '=distinct', 'format': 'int', 'tone': "=distinct >= 2 ? 'ok' : 'warn'"}]},
   {'type': 'checks', 'items': [{'label': '@chkFormat', 'ok': '=fmtOk', 'why': '@whyFormat'},
                                {'label': '@chkCat', 'ok': '=catOk', 'why': '@whyCat'},
                                {'label': '@chkNum', 'ok': '=fmtOk && numOk', 'why': '@whyNum'}]},
   {'type': 'note', 'when': '=!real', 'tone': 'info', 'text': '@simNote'}]},
 real_for('chat', {'system': '{sysText}', 'user': '{text}', 'maxTokens': 40}))

